VALUES (55123, 'tt0161023', NULL, 'Tumbleweeds', 'Tumbleweeds', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/2SdW45O7bPDTe0zLzNHhEcacNAk.jpg', 'https://image.tmdb.org/t/p/original/3lJvJAuPq4nSXRZwGvqaZX1eM2P.jpg', 'Whenever trouble strikes in one of her relationships, single mother Mary Jo Walker and her daughter, Ava, pack up and move to another city, a routine Ava is tiring of. This time, they are helped on their move to San Diego by trucker Jack Ranson. While Ava settles in, getting a leading part in the school play, Jack starts dating Mary Jo but soon reveals himself to be controlling and aggressive. Mary Jo prepares to flee again, angering Ava.', NULL, NULL, 1.1641, 6.4, 0, 9.52, '2026-11-03 02:32:44', '2026-11-03 02:32:44')
