VALUES (14926, 'tt0263757', NULL, 'Uptown Girls', 'Uptown Girls', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/r1zk8Dao6N1FDxax4QyC3O1IHpT.jpg', 'https://image.tmdb.org/t/p/original/mS3RlvaPIOLftOZaW5Droa9L9Yz.jpg', 'Molly Gunn, the freewheeling daughter of a deceased rock legend, is forced to get a job when her manager steals her money. As nanny to Ray - the precocious, oft-ignored daughter of a music executive - she learns what it means to be an adult while teaching Ray how to be a child.', NULL, NULL, 6.7363, 7.076, 0, 4.20856756756756737e+01, '2026-07-15 12:01:52', '2026-11-03 02:32:44')
