VALUES (236, 'tt0110598', NULL, 'Muriel''s Wedding', 'Muriel''s Wedding', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/zJyTr8Fo412a2OIfJGXTRAm4IwX.jpg', 'https://image.tmdb.org/t/p/original/x4sqnmV2nAKIG6cmt9WAF9xRA2M.jpg', 'Socially awkward Muriel Heslop wants nothing more than to get married. Unfortunately, due to her oppressive politician father, Muriel has never even been on a date. Ostracized by her more socially adept friends, Muriel runs into fellow outcast Rhonda Epinstalk, and the two move from their small Australian town to the big city of Sydney, where Muriel changes her name and begins the arduous task of redesigning her life to match her fantasies.', NULL, NULL, 2.9319, 6.8, 0, 7.54666666666666685e+00, '2026-08-04 03:20:13', '2026-11-03 02:32:44')
